-- Roadshow Cédric, version itinéraire.
-- On repart de zéro sur ses lieux : l'ancien lot était trié par nom, ce qui
-- n'aide personne sur le trottoir, et mélangeait des adresses qui ne se
-- prêtent pas à Lucky (tabacs, vente à emporter).
delete from crm_venues
where owner_email = 'descouturescedric@gmail.com'
  and import_key like 'roadshow-cedric-%'
  and stage = 'prospect'
  and not exists (select 1 from crm_notes n where n.crm_venue_id = crm_venues.id);

insert into crm_venues
  (name, city, type, category, address, siren, legal_name, latitude, longitude,
   roadshow_date, roadshow_label, roadshow_order, import_key,
   stage, source, owner_email, created_by, country)
select v.name, v.city, v.type, v.category, v.address, v.siren, v.legal_name, v.latitude, v.longitude,
       v.roadshow_date, v.roadshow_label, v.roadshow_order, v.import_key,
       'prospect', 'roadshow', 'descouturescedric@gmail.com', 'rodolph@lucky-app.io', 'FR'
